<?php
require_once __DIR__ . '/../../app/bootstrap.php';
$admin = require_admin();
$users = db()->query('SELECT u.*, r.slug role_slug, r.name role_name FROM users u JOIN roles r ON r.id=u.role_id ORDER BY u.name')->fetchAll();
$notice = flash('notice'); $error = flash('error'); layout_start('Usuarios', $admin);
?><div class="toolbar"><div><p class="eyebrow">Administración central</p><h1>Usuarios</h1><p>Gestiona los accesos y roles del portal.</p></div><a class="button" href="<?= e(app_url('admin/user-form.php')) ?>">Nuevo usuario</a></div><?= alert_html($notice, 'success') ?><?= alert_html($error) ?><section class="content-card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Usuario</th><th>Correo</th><th>Rol</th><th>Estado</th><th>Último acceso</th><th>Acciones</th></tr></thead><tbody><?php if (!$users): ?><tr><td class="empty-state" colspan="6">No hay usuarios registrados.</td></tr><?php else: foreach ($users as $item): ?><tr><td><strong><?= e($item['name']) ?></strong></td><td><?= e($item['email']) ?></td><td><?= e($item['role_name']) ?></td><td><span class="status <?= $item['active'] ? 'active' : 'inactive' ?>"><?= $item['active'] ? 'Activo' : 'Inactivo' ?></span></td><td class="muted"><?= $item['last_login_at'] ? e(date('d/m/Y H:i', strtotime($item['last_login_at']))) : 'Nunca' ?></td><td><a class="button secondary small-button" href="<?= e(app_url('admin/user-form.php?id=' . (int)$item['id'])) ?>">Editar</a></td></tr><?php endforeach; endif; ?></tbody></table></div></section><?php layout_end();
